<template>
  <main class="obs-page" :class="{ 'is-dark': theme.dark, 'is-motion-paused': motionPaused }" :style="themeStyle" data-mci-ui-root>
    <header class="obs-hero">
      <div class="obs-hero__mark" aria-hidden="true">⌁</div>
      <div class="obs-hero__copy">
        <p class="obs-eyebrow">SYSTEM OBSERVABILITY</p>
        <h1>系统日志/监控</h1>
        <p>从当前 API 节点定位高 CPU、热点接口、来源 IP、帐号与匿名流量、上传下载、未归因网络开销及系统日志；所有结论均标注数据范围。</p>
      </div>
      <div class="obs-hero__actions">
        <label><span>统计范围</span><select v-model="rangeKey" @change="changeAnalysisRange"><option v-for="item in rangeOptions" :key="item.key" :value="item.key">{{ item.label }}</option></select></label>
        <label><span>实时采样</span><select v-model.number="windowMinutes" @change="refreshActive"><option :value="1">1 分钟</option><option :value="5">5 分钟</option><option :value="15">15 分钟</option></select></label>
        <label class="obs-switch"><input v-model="autoRefresh" type="checkbox"><span></span><b>{{ autoRefresh ? '自动刷新' : '已暂停' }}</b></label>
        <button type="button" :disabled="loading" @click="refreshActive(true)">{{ loading ? '刷新中…' : '立即刷新' }}</button>
      </div>
    </header>

    <aside v-if="error" class="obs-feedback is-danger" role="alert"><b>读取失败</b><span>{{ error }}</span><button type="button" @click="error = ''">×</button></aside>
    <aside v-if="notice" class="obs-feedback is-success" role="status"><b>操作成功</b><span>{{ notice }}</span><button type="button" @click="notice = ''">×</button></aside>
    <aside v-if="scopeBoundary" class="obs-boundary"><b>数据边界</b><span>{{ scopeBoundary }}</span></aside>
    <aside v-if="legacyMenus.length" class="obs-migration">
      <div><b>检测到 {{ legacyMenus.length }} 个官方旧菜单</b><span>应用包不会静默删除租户菜单。确认后仅软删除名称、地址与官方固定标识均一致的旧“系统日志/系统监控”菜单；已改作其它用途的菜单会失败关闭。</span><small>{{ legacyMenus.map(item => item.Name).join('、') }}</small></div>
      <button type="button" @click="openLegacyMigration">完成旧菜单合并</button>
    </aside>

    <nav class="obs-tabs" aria-label="系统日志与监控功能">
      <button v-for="tab in tabs" :key="tab.key" type="button" :class="{ 'is-active': activeTab === tab.key }" @click="selectTab(tab.key)"><span aria-hidden="true">{{ tab.icon }}</span>{{ tab.label }}<em v-if="tab.key === 'requests' && activeCount">{{ activeCount }}</em></button>
    </nav>

    <section v-if="activeTab === 'overview'" class="obs-stack">
      <div v-if="!snapshot" class="obs-skeleton"><i v-for="n in 10" :key="n"></i></div>
      <template v-else>
        <div class="obs-metrics">
          <article><span>进程 CPU（主机归一）</span><strong :class="metricTone(process.ProcessCpuPercentNormalized, 70, 90)">{{ number(process.ProcessCpuPercentNormalized, 1) }}%</strong><small>{{ node.ProcessorCount || 1 }} 个逻辑处理器</small></article>
          <article title="多核原始值是各 CPU 核心用量之和，可以超过 100%；247.7% 约等于持续占用 2.48 个逻辑核心，是否异常应以主机归一值、持续时间和热点请求共同判断。"><span>进程 CPU（多核原始）</span><strong :class="metricTone(process.ProcessCpuPercentNormalized, 70, 90)">{{ number(process.ProcessCpuPercentRaw, 1) }}%</strong><small>约 {{ number(Number(process.ProcessCpuPercentRaw || 0) / 100, 2) }} 核，可高于 100%</small></article>
          <article><span>请求速率</span><strong>{{ number(analysisRequests.RequestsPerSecond, 2) }}</strong><small>次/秒，{{ analysisRequests.BusinessRequestCount || analysisRequests.RequestCount || 0 }} 个业务请求</small></article>
          <article><span>{{ analysisRequests.P95DurationMs == null ? '最大耗时' : 'P95 耗时' }}</span><strong :class="metricTone(analysisRequests.P95DurationMs ?? analysisRequests.MaxDurationMs, 1000, 2500)">{{ duration(analysisRequests.P95DurationMs ?? analysisRequests.MaxDurationMs) }}</strong><small>平均 {{ duration(analysisRequests.AverageDurationMs) }} · {{ analysisRangeLabel }}</small></article>
          <article><span>活动请求</span><strong :class="metricTone(requests.ActiveBusinessRequestCount, Math.max(8, (node.ProcessorCount || 1) * 2), Math.max(16, (node.ProcessorCount || 1) * 4))">{{ requests.ActiveBusinessRequestCount || 0 }}</strong><small>诊断请求已单独计算</small></article>
          <article><span>异常率</span><strong :class="metricTone(analysisRequests.ErrorRate, 5, 15)">{{ number(analysisRequests.ErrorRate, 1) }}%</strong><small>{{ analysisRequests.ErrorCount || 0 }} 个 4xx/5xx/异常 · {{ analysisRangeLabel }}</small></article>
          <article><span>工作集内存</span><strong>{{ number(process.WorkingSetMB, 0) }} MB</strong><small>托管堆 {{ number(process.ManagedHeapMB, 0) }} MB</small></article>
          <article><span>线程池余量</span><strong>{{ process.ThreadPoolAvailableWorkers || 0 }}</strong><small>最大 {{ process.ThreadPoolMaxWorkers || 0 }}，进程线程 {{ process.ProcessThreadCount || 0 }}</small></article>
        </div>

        <section class="obs-diagnosis" :class="`is-${String(diagnosis.Severity || 'Info').toLowerCase()}`">
          <div class="obs-diagnosis__lead"><span aria-hidden="true">{{ diagnosisIcon }}</span><div><p class="obs-eyebrow">实时诊断 · 置信度 {{ confidenceText }}</p><h2>{{ diagnosis.Summary }}</h2><p>{{ diagnosis.Boundary }}</p></div></div>
          <div class="obs-diagnosis__signals"><article v-for="signal in diagnosis.Signals || []" :key="signal.Code"><b>{{ signal.Title }}</b><span>{{ signal.Detail }}</span></article></div>
          <ol><li v-for="item in diagnosis.Recommendations || []" :key="item">{{ item }}</li></ol>
        </section>

        <div class="obs-grid obs-grid--2">
          <section class="obs-panel"><header><div><h2>热点接口</h2><p>“耗时占比”是所选范围内接口累计耗时贡献，不是 CPU 占比；高占比需要结合平均/P95（历史为最大）、调用量和 CPU 归一值判断。</p></div><span>{{ analysisRangeLabel }}</span></header><ObservabilityTable :rows="analysisTopEndpoints" :columns="endpointColumns" row-key="Key" empty-text="所选范围没有业务请求汇总"><template #cell-endpoint="{ row }"><b>{{ row.ApiEngineKey || row.Route || row.Key }}</b><small>{{ row.EndpointKind }} · {{ row.Key }}</small></template><template #cell-requests="{ row }">{{ row.RequestCount }}<small>{{ number(row.RequestsPerSecond, 2) }}/s · 活动 {{ row.ActiveCount || 0 }}</small></template><template #cell-share="{ row }"><div class="obs-bar"><i :style="{ width: `${Math.min(100, Number(row.CostSharePercent || 0))}%` }"></i></div>{{ number(row.CostSharePercent, 1) }}%</template><template #cell-duration="{ row }">{{ duration(row.AverageDurationMs) }} / {{ duration(row.P95DurationMs ?? row.MaxDurationMs) }}</template><template #cell-errors="{ row }"><span :class="{ 'is-danger-text': row.ErrorCount }">{{ row.ErrorCount }}（{{ number(row.ErrorRate, 1) }}%）</span></template></ObservabilityTable></section>
          <section class="obs-panel"><header><div><h2>来源 IP</h2><p>按请求耗时贡献排序；封禁前确认反向代理与容器网关。</p></div><span>{{ analysisRangeLabel }}</span></header><ObservabilityTable :rows="analysisTopIps" :columns="ipColumns" row-key="Key" empty-text="暂无来源 IP 聚合"><template #cell-ip="{ row }"><b>{{ row.Ip || row.Key }}</b></template><template #cell-requests="{ row }">{{ row.RequestCount }} / {{ row.ActiveCount || 0 }}</template><template #cell-share="{ row }">{{ number(row.CostSharePercent, 1) }}%</template><template #cell-errors="{ row }"><span :class="{ 'is-danger-text': row.ErrorCount }">{{ row.ErrorCount }}</span></template><template #cell-action="{ row }"><button class="obs-link is-danger" type="button" @click.stop="openBlock(row.Ip || row.Key)">封禁</button></template></ObservabilityTable></section>
        </div>
      </template>
    </section>

    <section v-else-if="activeTab === 'traffic'" class="obs-stack obs-traffic-cockpit">
      <div v-if="!snapshot" class="obs-skeleton"><i v-for="n in 10" :key="n"></i></div>
      <template v-else>
        <aside class="obs-traffic-status" :class="`is-${trafficStatusMeta.tone}`">
          <span class="obs-live-dot" aria-hidden="true"></span>
          <div><b>{{ trafficStatusMeta.title }}</b><p>{{ trafficStatusMeta.detail }}</p></div>
          <em>{{ number(traffic.CoverageSeconds, 0) }}s 覆盖 · {{ traffic.Scope || '-' }}</em>
        </aside>

        <div class="obs-metrics obs-metrics--traffic">
          <article class="obs-cockpit-panel"><span>网卡累计接收</span><strong>{{ bytes(traffic.InterfaceTotalReceivedBytes) }}</strong><small>当前命名空间/宿主网卡计数</small></article>
          <article class="obs-cockpit-panel"><span>网卡累计发送</span><strong>{{ bytes(traffic.InterfaceTotalSentBytes) }}</strong><small>可与容器 NetIO 对照</small></article>
          <article class="obs-cockpit-panel"><span>范围 HTTP 接收</span><strong>{{ bytes(analysisTraffic.AccountedHttpReceivedBytes) }}</strong><small>{{ analysisRangeLabel }}请求体</small></article>
          <article class="obs-cockpit-panel"><span>范围 HTTP 发送</span><strong>{{ bytes(analysisTraffic.AccountedHttpSentBytes) }}</strong><small>{{ analysisRangeLabel }}响应体</small></article>
          <article class="obs-cockpit-panel" :class="{ 'is-alert-card': trafficResidualRatio >= 50 }" :title="trafficStatusMeta.solution"><span>未归因流量</span><strong :class="{ 'is-danger-text': trafficResidualRatio >= 50 }">{{ bytes((traffic.UnattributedReceivedBytes || 0) + (traffic.UnattributedSentBytes || 0)) }}</strong><small>{{ number(trafficResidualRatio, 1) }}% · 查看原因与方案</small></article>
          <article class="obs-cockpit-panel" :class="{ 'is-alert-card': analysisTraffic.SuspiciousCount > 0 }" title="可疑样本会异步保留到 MongoDB 系统日志，固定时间桶汇总写入 MySQL；核对来源、权限、限流与对象存储策略。"><span>可疑 / 大流量</span><strong :class="{ 'is-danger-text': analysisTraffic.SuspiciousCount > 0 }">{{ analysisTraffic.SuspiciousCount || 0 }} / {{ analysisTraffic.LargeTransferCount || 0 }}</strong><small>匿名请求 {{ analysisTraffic.AnonymousRequestCount || 0 }}</small></article>
        </div>

        <section class="obs-panel obs-cockpit-panel obs-traffic-explain">
          <header><div><h2>流量归因边界与处置建议</h2><p>Docker NetIO 包含应用 HTTP、协议开销和服务端对外/内部网络，并不等于“用户下载量”。</p></div><span>HTTP 已归因 {{ number(traffic.AttributionPercent, 1) }}%</span></header>
          <div class="obs-traffic-boundaries"><article v-for="item in analysisTraffic.Boundaries || traffic.Boundaries || []" :key="item"><i aria-hidden="true">i</i><span>{{ item }}</span></article></div>
          <p class="obs-solution"><b>当前建议：</b>{{ trafficStatusMeta.solution }}</p>
        </section>

        <div class="obs-grid obs-grid--2">
          <section class="obs-panel obs-cockpit-panel"><header><div><h2>实时收发速率</h2><p>网卡计数采样；页面隐藏或系统要求减少动画时自动暂停视觉效果。</p></div><span>↓ {{ rate(traffic.ReceiveBytesPerSecond) }} · ↑ {{ rate(traffic.SendBytesPerSecond) }}</span></header><svg class="obs-trend obs-trend--traffic" viewBox="0 0 100 60" preserveAspectRatio="none" role="img" aria-label="网络实时接收和发送趋势"><polyline class="is-primary" :points="trendPoints('trafficRx')"/><polyline class="is-secondary" :points="trendPoints('trafficTx')"/></svg><div class="obs-legend"><span><i class="is-primary"></i>接收</span><span><i class="is-secondary"></i>发送</span></div></section>
          <section class="obs-panel obs-cockpit-panel"><header><div><h2>{{ analysisRangeLabel }} MySQL 汇总趋势</h2><p>短期使用 5 分钟/小时桶，长期使用天桶；跨刷新与重启可回读，写入幂等且不会扫描 MongoDB 明细。</p></div><span>{{ trafficHistory.length }} 个节点桶</span></header><svg class="obs-trend obs-trend--traffic" viewBox="0 0 100 60" preserveAspectRatio="none" role="img" :aria-label="`${analysisRangeLabel}网络流量趋势`"><polyline class="is-primary" :points="trafficHistoryPoints('ReceivedBytes')"/><polyline class="is-secondary" :points="trafficHistoryPoints('SentBytes')"/></svg><p v-if="trafficHistoryError" class="obs-inline-warning">{{ trafficHistoryError }}</p><div class="obs-legend"><span><i class="is-primary"></i>接收</span><span><i class="is-secondary"></i>发送</span></div></section>
        </div>

        <section class="obs-panel obs-cockpit-panel"><header><div><h2>流量热点接口</h2><p>按请求体 + 响应体总字节排序；用于定位大响应、无分页接口、重复轮询和文件传输。</p></div><span>{{ analysisRangeLabel }} · TOP {{ analysisTraffic.TopEndpoints?.length || 0 }}</span></header><ObservabilityTable :rows="analysisTraffic.TopEndpoints || []" :columns="trafficDimensionColumns" row-key="Key" :row-class="trafficRowClass" empty-text="所选范围暂无 HTTP 流量汇总"><template #cell-dimension="{ row }"><b class="obs-two-line" :title="row.Key">{{ row.Key }}</b><small>{{ endpointKind(row.Key) }}</small></template><template #cell-flow="{ row }"><b>{{ bytes(row.TotalBytes) }}</b><small>↓ {{ bytes(row.ReceivedBytes) }} · ↑ {{ bytes(row.SentBytes) }}</small></template><template #cell-share="{ row }"><div class="obs-bar"><i :style="{ width: `${Math.min(100, Number(row.TrafficSharePercent || 0))}%` }"></i></div>{{ number(row.TrafficSharePercent, 1) }}%</template><template #cell-requests="{ row }">{{ row.RequestCount }}<small>上传 {{ row.UploadCount }} · 下载 {{ row.DownloadCount }}</small></template><template #cell-risk="{ row }"><span class="obs-risk" :class="`is-${String(row.RiskLevel || 'normal').toLowerCase()}`" :title="trafficRiskTooltip(row)">{{ riskLabel(row.RiskLevel) }}</span></template></ObservabilityTable></section>

        <div class="obs-grid obs-grid--2">
          <section class="obs-panel obs-cockpit-panel"><header><div><h2>来源 IP</h2><p>回答“谁从哪个 IP 发来/取走了多少”；封禁前先确认反向代理和容器网关。</p></div></header><ObservabilityTable :rows="analysisTraffic.TopIps || []" :columns="trafficIpColumns" row-key="Key" :row-class="trafficRowClass" empty-text="暂无来源 IP"><template #cell-dimension="{ row }"><b>{{ row.Key }}</b></template><template #cell-flow="{ row }"><b>{{ bytes(row.TotalBytes) }}</b><small>↓ {{ bytes(row.ReceivedBytes) }} · ↑ {{ bytes(row.SentBytes) }}</small></template><template #cell-requests="{ row }">{{ row.RequestCount }}<small>异常 {{ row.ErrorCount }} · 匿名 {{ row.AnonymousCount }}</small></template><template #cell-risk="{ row }"><span class="obs-risk" :class="`is-${String(row.RiskLevel || 'normal').toLowerCase()}`" :title="trafficRiskTooltip(row)">{{ riskLabel(row.RiskLevel) }}</span></template><template #cell-action="{ row }"><button class="obs-link is-danger" type="button" @click.stop="openBlock(row.Key)">封禁</button></template></ObservabilityTable></section>
          <section class="obs-panel obs-cockpit-panel"><header><div><h2>帐号 / 匿名</h2><p>授权完成后按帐号聚合；未携带有效平台身份的请求统一标记匿名。</p></div></header><ObservabilityTable :rows="analysisTraffic.TopUsers || []" :columns="trafficIdentityColumns" row-key="Key" :row-class="trafficRowClass" empty-text="暂无用户流量"><template #cell-dimension="{ row }"><b class="obs-two-line" :title="row.Key">{{ row.Key }}</b></template><template #cell-flow="{ row }"><b>{{ bytes(row.TotalBytes) }}</b><small>↓ {{ bytes(row.ReceivedBytes) }} · ↑ {{ bytes(row.SentBytes) }}</small></template><template #cell-requests="{ row }">{{ row.RequestCount }}<small>异常 {{ row.ErrorCount }} · 可疑 {{ row.SuspiciousCount }}</small></template><template #cell-risk="{ row }"><span class="obs-risk" :class="`is-${String(row.RiskLevel || 'normal').toLowerCase()}`" :title="trafficRiskTooltip(row)">{{ riskLabel(row.RiskLevel) }}</span></template></ObservabilityTable></section>
        </div>

        <div class="obs-grid obs-grid--2">
          <section class="obs-panel obs-cockpit-panel"><header><div><h2>租户流量</h2><p>多租户 API 节点按请求租户标识聚合。</p></div></header><ObservabilityTable :rows="analysisTraffic.TopTenants || []" :columns="trafficIdentityColumns" row-key="Key" :row-class="trafficRowClass" empty-text="暂无租户流量"><template #cell-dimension="{ row }"><b>{{ row.Key }}</b></template><template #cell-flow="{ row }"><b>{{ bytes(row.TotalBytes) }}</b><small>↓ {{ bytes(row.ReceivedBytes) }} · ↑ {{ bytes(row.SentBytes) }}</small></template><template #cell-requests="{ row }">{{ row.RequestCount }}<small>异常 {{ row.ErrorCount }}</small></template><template #cell-risk="{ row }"><span class="obs-risk" :class="`is-${String(row.RiskLevel || 'normal').toLowerCase()}`" :title="trafficRiskTooltip(row)">{{ riskLabel(row.RiskLevel) }}</span></template></ObservabilityTable></section>
          <section class="obs-panel obs-cockpit-panel"><header><div><h2>内容类型</h2><p>识别 JSON 大响应、二进制下载、表单上传等资源类型。</p></div></header><ObservabilityTable :rows="analysisTraffic.TopContentTypes || []" :columns="trafficIdentityColumns" row-key="Key" :row-class="trafficRowClass" empty-text="暂无内容类型流量"><template #cell-dimension="{ row }"><b class="obs-two-line" :title="row.Key">{{ row.Key }}</b></template><template #cell-flow="{ row }"><b>{{ bytes(row.TotalBytes) }}</b><small>↓ {{ bytes(row.ReceivedBytes) }} · ↑ {{ bytes(row.SentBytes) }}</small></template><template #cell-requests="{ row }">{{ row.RequestCount }}<small>上传 {{ row.UploadCount }} · 下载 {{ row.DownloadCount }}</small></template><template #cell-risk="{ row }"><span class="obs-risk" :class="`is-${String(row.RiskLevel || 'normal').toLowerCase()}`" :title="trafficRiskTooltip(row)">{{ riskLabel(row.RiskLevel) }}</span></template></ObservabilityTable></section>
        </div>

        <section class="obs-panel obs-cockpit-panel"><header><div><h2>{{ analysisRangeLabel }}大文件 / 可疑传输明细</h2><p>跨月分页读取 MongoDB 中的高价值样本，可定位接口、帐号、IP、文件名/类型和收发字节；不保存正文、文件内容或身份凭据。</p></div><span>MongoDB 明细 {{ trafficDetailCount }}</span></header><ObservabilityTable :rows="trafficDetails" :columns="trafficTransferColumns" :row-key="row => row.EventId || `${row.TraceId}-${row.CompletedAtUtc}`" :row-class="trafficRowClass" server :total="trafficDetailCount" :page="trafficDetailPage" :page-size="trafficDetailPageSize" :loading="trafficDetailLoading" search-placeholder="搜索接口、帐号、IP、文件名或类型…" empty-text="所选范围没有大流量、上传下载或可疑传输" @update:page="loadTrafficDetails" @update:page-size="changeTrafficDetailPageSize" @search="searchTrafficDetails"><template #cell-endpoint="{ row }"><b class="obs-two-line" :title="row.ApiEngineKey || row.Route">{{ row.ApiEngineKey || row.Route }}</b><small class="obs-two-line">{{ row.Method || '-' }} · {{ row.RequestContentType || '-' }} → {{ row.ResponseContentType || '-' }}</small><small v-if="row.FileCount" class="obs-two-line" :title="(row.FileNames || []).join('、')">文件 {{ row.FileCount }} 个 · {{ (row.FileNames || []).join('、') || (row.FileExtensions || []).join('、') || '名称未提供' }}</small></template><template #cell-actor="{ row }"><b>{{ row.Actor || row.Account || '匿名' }}</b><small>{{ row.Ip }} · {{ row.OsClient || 'unknown' }}</small></template><template #cell-flow="{ row }"><b>{{ bytes(row.TotalBytes) }}</b><small>接收 {{ bytes(row.ReceivedBytes) }} · 发送 {{ bytes(row.SentBytes) }}</small></template><template #cell-risk="{ row }"><span class="obs-risk" :class="`is-${String(row.RiskLevel || 'normal').toLowerCase()}`" :title="trafficRiskTooltip(row)">{{ riskLabel(row.RiskLevel) }}</span><small class="obs-two-line" :title="trafficRiskTooltip(row)">{{ row.RiskReason }}</small></template><template #cell-time="{ row }">{{ formatTime(row.CompletedAtUtc) }}<small>{{ duration(row.ElapsedMs) }} · HTTP {{ row.StatusCode }}</small><button v-if="row.TraceId" class="obs-trace" type="button" @click.stop="openTraceFromTraffic(row)">Trace {{ row.TraceId }}</button></template></ObservabilityTable></section>
      </template>
    </section>

    <section v-else-if="activeTab === 'requests'" class="obs-stack">
      <div class="obs-grid obs-grid--2">
        <section class="obs-panel"><header><div><h2>正在执行</h2><p>持续时间长且并发集中的请求，是 CPU/线程池归因的重要线索。</p></div><span>{{ activeRequests.length }} 个</span></header><ObservabilityTable :rows="activeRequests" :columns="activeRequestColumns" :row-key="row => `${row.TraceId}-${row.StartedAtUtc}`" empty-text="当前没有仍在执行的业务请求"><template #cell-endpoint="{ row }"><b>{{ row.ApiEngineKey || row.Route }}</b><small>{{ row.Method }} · {{ row.TraceId || '无 TraceId' }}</small></template><template #cell-elapsed="{ row }"><span :class="{ 'is-danger-text': row.ElapsedMs >= 5000 }">{{ duration(row.ElapsedMs) }}</span></template></ObservabilityTable></section>
        <section class="obs-panel"><header><div><h2>最近完成</h2><p>只保留内存中的少量样本，不包含查询串、请求体与身份凭据。</p></div><span>最新 {{ recentRequests.length }}</span></header><ObservabilityTable :rows="recentRequests" :columns="recentRequestColumns" :row-key="row => `${row.TraceId}-${row.CompletedAtUtc}`" empty-text="暂无已完成请求样本"><template #cell-endpoint="{ row }"><b>{{ row.ApiEngineKey || row.Route }}</b><small>{{ row.Method }} · {{ row.TraceId || '无 TraceId' }}</small></template><template #cell-status="{ row }"><span :class="{ 'is-danger-text': row.StatusCode >= 400 }">{{ row.StatusCode }}</span></template><template #cell-elapsed="{ row }">{{ duration(row.ElapsedMs) }}</template></ObservabilityTable></section>
      </div>
    </section>

    <section v-else-if="activeTab === 'runtime'" class="obs-stack">
      <div class="obs-metrics obs-metrics--compact">
        <article v-for="item in platformMetricCards" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.note }}</small></article>
      </div>
      <div class="obs-grid obs-grid--3">
        <section class="obs-panel obs-kv"><header><div><h2>操作系统 / 进程</h2><p>当前命中的 API 节点</p></div></header><dl><template v-for="item in runtimeRows" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></template></dl></section>
        <section class="obs-panel obs-kv"><header><div><h2>主机 CPU / 内存</h2><p>与进程指标分开查看</p></div></header><dl><template v-for="item in hostMetricRows" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></template></dl></section>
        <section class="obs-panel obs-kv"><header><div><h2>网络 / 磁盘 IO</h2><p>瞬时采样只代表当前节点</p></div></header><dl><template v-for="item in ioRows" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></template></dl></section>
      </div>
      <div class="obs-grid obs-grid--2">
        <section class="obs-panel"><header><div><h2>CPU / 内存趋势</h2><p>当前页面会话最近 {{ trends.length }} 个采样点</p></div><span>CPU {{ number(latestTrend.cpu, 1) }}% · RAM {{ number(latestTrend.mem, 1) }}%</span></header><svg class="obs-trend" viewBox="0 0 100 60" preserveAspectRatio="none" role="img" aria-label="CPU 和内存使用率趋势"><polyline class="is-primary" :points="trendPoints('cpu', 100)"/><polyline class="is-secondary" :points="trendPoints('mem', 100)"/></svg><div class="obs-legend"><span><i class="is-primary"></i>CPU</span><span><i class="is-secondary"></i>内存</span></div></section>
        <section class="obs-panel"><header><div><h2>网络流量趋势</h2><p>接收与发送速率，按当前样本峰值缩放</p></div><span>↓ {{ rate(latestTrend.rx) }} · ↑ {{ rate(latestTrend.tx) }}</span></header><svg class="obs-trend" viewBox="0 0 100 60" preserveAspectRatio="none" role="img" aria-label="网络接收和发送趋势"><polyline class="is-primary" :points="trendPoints('rx')"/><polyline class="is-secondary" :points="trendPoints('tx')"/></svg><div class="obs-legend"><span><i class="is-primary"></i>接收</span><span><i class="is-secondary"></i>发送</span></div></section>
      </div>
      <section class="obs-panel"><header><div><h2>磁盘</h2><p>容量、可用空间和使用率</p></div></header><div class="obs-card-list"><article v-for="disk in disks" :key="disk.Filesystem || disk.MountPoint"><b>{{ disk.Filesystem || disk.MountPoint || '磁盘' }}</b><span>{{ disk.FreeGB ?? '-' }} GB 可用 / {{ disk.TotalGB ?? '-' }} GB</span><div class="obs-bar"><i :style="{ width: `${Math.min(100, Number(disk.UsagePercent || 0))}%` }"></i></div></article><p v-if="!disks.length" class="obs-empty-cell">当前节点未返回磁盘详情</p></div></section>
      <section class="obs-panel"><header><div><h2>Docker 容器</h2><p>容器状态、CPU、内存、网络、块 IO 与进程数；命令采样较重，最多每 30 秒自动更新一次。</p></div><button class="obs-link" type="button" :disabled="dockerLoading" @click="loadDocker(true)">{{ dockerLoading ? '读取中…' : '刷新 Docker 指标' }}</button></header><div v-if="docker?.Available" class="obs-metrics obs-metrics--compact"><article><span>Docker</span><strong>{{ docker.DockerVersion || '-' }}</strong><small>服务端版本</small></article><article><span>运行容器</span><strong>{{ docker.ContainersRunning || 0 }}</strong><small>共 {{ docker.ContainersTotal || 0 }}</small></article><article><span>停止容器</span><strong>{{ docker.ContainersStopped || 0 }}</strong><small>当前节点</small></article><article><span>镜像</span><strong>{{ docker.Images || 0 }}</strong><small>本地镜像</small></article></div><p v-else-if="docker" class="obs-empty-cell">{{ docker.Msg || 'Docker 未安装或未运行' }}</p><ObservabilityTable v-if="docker?.Available" :rows="dockerContainers" :columns="dockerColumns" row-key="ContainerId" empty-text="暂无容器"><template #cell-container="{ row }"><b>{{ row.Name || '-' }}</b><small>{{ row.ContainerId }} · {{ row.State || row.Status }}</small></template><template #cell-image="{ row }"><span class="obs-wrap">{{ row.Image || '-' }}</span><small>{{ row.Ports || '-' }}</small></template><template #cell-cpu="{ row }"><div class="obs-bar"><i :style="{ width: `${Math.min(100, Number(row.CPUPercNum || 0))}%` }"></i></div>{{ row.CPUPerc || '0.00%' }}</template><template #cell-memory="{ row }"><div class="obs-bar"><i :style="{ width: `${Math.min(100, Number(row.MemPercNum || 0))}%` }"></i></div>{{ row.MemUsage || '-' }} · {{ row.MemPerc || '0.00%' }}</template></ObservabilityTable></section>
      <div class="obs-grid obs-grid--3">
        <section class="obs-panel"><header><div><h2>接口引擎调用排行</h2><p>MongoDB 累计调用次数 TOP10</p></div></header><ObservabilityTable :rows="apiEngineRank" :columns="apiRankColumns" :row-key="row => row.Id || row.ApiEngineKey" empty-text="暂无接口调用排行"><template #cell-engine="{ row }"><b>{{ row.Name || row.ApiEngineKey || '-' }}</b><small>{{ row.ApiEngineKey || '-' }}</small></template><template #cell-time="{ row }">{{ formatTime(row.LastCallTime) }}</template></ObservabilityTable></section>
        <section class="obs-panel"><header><div><h2>表数据量排行</h2><p>表单引擎 DataCount TOP10</p></div></header><ObservabilityTable :rows="tableDataRank" :columns="tableRankColumns" :row-key="row => row.Id || row.Name" empty-text="暂无表数据量排行" /></section>
        <section class="obs-panel"><header><div><h2>最近登录用户</h2><p>当前租户最近登录记录</p></div></header><ObservabilityTable :rows="recentLogins" :columns="loginColumns" row-key="Id" empty-text="暂无最近登录记录"><template #cell-user="{ row }"><b>{{ row.Name || '-' }}</b><small>{{ row.Account || '-' }}</small></template><template #cell-time="{ row }">{{ formatTime(row.LastLoginTime) }}</template></ObservabilityTable></section>
      </div>
    </section>

    <section v-else-if="activeTab === 'logs'" class="obs-stack">
      <section class="obs-panel obs-log-panel"><header><div><h2>系统日志</h2><p>统一查看错误、警告、慢 SQL、慢执行、异常与平台行为；参数在可信后端脱敏后才返回详情。</p></div><span>{{ logCount }} 条</span></header>
        <div class="obs-quick-filters"><button v-for="item in logQuickFilters" :key="item.key" type="button" :class="{ 'is-active': isLogQuickActive(item) }" @click="applyLogQuickFilter(item)">{{ item.label }}</button></div>
        <div class="obs-log-stats"><button v-for="card in logStatCards" :key="card.key" type="button" :class="[`is-${card.tone}`, { 'is-active': isLogQuickActive(card) }]" @click="applyLogQuickFilter(card)"><span aria-hidden="true">{{ card.icon }}</span><strong>{{ card.value }}</strong><small>{{ card.label }}</small></button></div>
        <div class="obs-toolbar obs-toolbar--logs"><input v-model.trim="logFilters.Keyword" type="search" placeholder="搜索标题、内容、用户、IP、TraceId…" @keyup.enter="loadLogs(1,true)"><select v-model="logFilters.Type"><option value="">全部日志类型</option><option v-for="type in logTypes" :key="type" :value="type">{{ type }}</option></select><select v-model="logFilters.Level"><option value="">全部级别</option><option :value="0">调试</option><option :value="1">信息</option><option :value="2">警告</option><option :value="3">错误</option><option :value="4">严重</option></select><input v-model="logFilters.SearchMonth" type="month"><button type="button" @click="loadLogs(1,true)">查询</button><button class="is-secondary" type="button" @click="resetLogFilters">重置</button></div>
        <ObservabilityTable :rows="logs" :columns="logColumns" :server="true" :total="logCount" :page="logPage" :page-size="logPageSize" :page-sizes="[15,30,50,100,200]" :searchable="false" :loading="logLoading" row-key="Id" :row-class="logRowClass" :clickable="true" empty-text="没有匹配的系统日志" @update:page="page => loadLogs(page,false)" @update:page-size="changeLogPageSize" @row-click="openLogDetail"><template #cell-index="{ index }">{{ index + 1 }}</template><template #cell-level="{ row }"><span class="obs-level" :class="`is-${levelMeta(row.Level).tone}`" :title="logAnomalyTooltip(row)">{{ levelMeta(row.Level).label }}</span></template><template #cell-type="{ row }"><span class="obs-type">{{ row.Type || '-' }}</span><small>{{ row.Category || row.Source || '-' }}</small></template><template #cell-title="{ row }"><b class="obs-two-line" :title="row.Title || '-'">{{ row.Title || '-' }}</b><small class="obs-two-line" :title="row.Content || '-'">{{ row.Content || '-' }}</small></template><template #cell-user="{ row }">{{ row.UserName || '-' }}<small>{{ row.IP || '-' }}</small></template><template #cell-timer="{ row }"><span :class="metricTone(logDuration(row),1000,5000)" :title="logAnomalyTooltip(row)">{{ duration(logDuration(row)) }}</span><small v-if="row.TraceId">{{ row.TraceId }}</small></template><template #cell-time="{ row }">{{ formatTime(row.CreateTime || row.OccurredAt) }}</template></ObservabilityTable>
      </section>
    </section>

    <CdnMonitor v-else-if="activeTab === 'cdn'" ref="cdnMonitor" />
    <MemoryDiagnostics v-else-if="activeTab === 'memory'" ref="memoryDiagnostics" :query="query" @trace="openTraceFromTraffic" />

    <section v-else-if="activeTab === 'security'" class="obs-stack">
      <section class="obs-panel">
        <header><div><h2>安全访问与封禁</h2><p>原“安全访问日志、恶意攻击事件、IP 封锁记录”三个菜单的数据管理已合并到这里。</p></div><span>活动封禁 {{ activeBlocks.length }}</span></header>
        <div class="obs-subtabs"><button v-for="item in securityKinds" :key="item.key" type="button" :class="{ 'is-active': securityKind === item.key }" @click="selectSecurityKind(item.key)">{{ item.label }}</button></div>
        <div class="obs-toolbar"><input v-model.trim="securityKeyword" type="search" placeholder="按 IP 搜索" @keyup.enter="loadSecurity(1)"><button type="button" @click="loadSecurity(1)">查询</button><button class="is-danger" type="button" @click="openBlock('')">手动封禁 IP</button></div>
        <ObservabilityTable
          :rows="securityRows"
          :columns="securityColumns"
          :server="true"
          :total="securityCount"
          :page="securityPage"
          :page-size="securityPageSize"
          :searchable="false"
          row-key="Id"
          empty-text="暂无匹配记录"
          @update:page="loadSecurity"
          @update:page-size="changeSecurityPageSize"
        />
      </section>
      <section class="obs-panel"><header><div><h2>当前活动封禁</h2><p>跨节点 Redis 状态可用时以共享状态为准。</p></div></header><div class="obs-card-list"><article v-for="item in activeBlocks" :key="item.Ip"><b>{{ item.Ip }}</b><span>{{ item.Reason }} · 至 {{ formatTime(item.ExpiresAtUtc) }}</span><button class="obs-link" type="button" @click="confirmUnblock(item.Ip)">解封</button></article><p v-if="!activeBlocks.length" class="obs-empty-cell">当前没有活动 IP 封禁</p></div></section>
    </section>

    <section v-else class="obs-panel obs-app-logs">
      <header><div><h2>当前应用日志</h2><p>读取 API 进程内环形缓冲区，敏感键值会在可信后端脱敏；不是 Docker 完整历史日志。</p></div><button class="obs-link" type="button" :disabled="appLogLoading" @click="loadAppLogs">{{ appLogLoading ? '读取中…' : '刷新' }}</button></header>
      <div class="obs-toolbar"><select v-model.number="appLogLineCount" @change="loadAppLogs"><option :value="100">最近 100 行</option><option :value="200">最近 200 行</option><option :value="500">最近 500 行</option><option :value="1000">最近 1000 行</option></select><select v-model="appLogLevel"><option value="All">全部级别</option><option value="Error">错误</option><option value="Warn">警告</option><option value="Info">信息</option></select></div>
      <ObservabilityTable :rows="filteredAppLogRows" :columns="appLogColumns" row-key="key" search-placeholder="搜索应用日志…" empty-text="暂无应用日志"><template #cell-line="{ row }"><span class="obs-app-log-line" :class="`is-${row.tone}`">{{ row.line }}</span></template><template #cell-time="{ row }">{{ row.time || '-' }}</template><template #cell-level="{ row }"><span class="obs-level" :class="`is-${row.tone}`">{{ row.level }}</span></template><template #cell-message="{ row }"><code class="obs-app-log-message">{{ row.message }}</code></template></ObservabilityTable>
    </section>

    <Teleport to="body">
      <div v-if="logDetail" class="obs-dialog-mask" data-testid="observability-log-detail" @click.self="closeLogDetail">
        <section class="obs-dialog obs-dialog--large" role="dialog" aria-modal="true" aria-labelledby="obs-log-detail-title">
          <header class="obs-dialog__header"><div><p class="obs-eyebrow">MICROI DIALOG</p><h2 id="obs-log-detail-title">日志详情</h2></div><button type="button" aria-label="关闭日志详情" @click="closeLogDetail">×</button></header>
          <div class="obs-detail-grid">
            <dl><dt>日志级别</dt><dd><span class="obs-level" :class="`is-${levelMeta(logDetail.Level).tone}`">{{ levelMeta(logDetail.Level).label }}</span></dd></dl>
            <dl><dt>日志类型</dt><dd><span class="obs-type">{{ logDetail.Type || '-' }}</span></dd></dl>
            <dl><dt>耗时</dt><dd><span :class="metricTone(logDuration(logDetail),1000,5000)">{{ duration(logDuration(logDetail)) }}</span></dd></dl>
            <dl><dt>用户</dt><dd>{{ logDetail.UserName || '-' }}</dd></dl>
            <dl><dt>IP</dt><dd>{{ logDetail.IP || '-' }}</dd></dl>
            <dl><dt>创建时间</dt><dd>{{ formatTime(logDetail.CreateTime || logDetail.OccurredAt) }}</dd></dl>
            <dl><dt>Api</dt><dd>{{ logDetail.Api || '-' }}</dd></dl>
            <dl><dt>AppId</dt><dd>{{ logDetail.AppId || '-' }}</dd></dl>
            <dl><dt>请求方式</dt><dd>{{ logDetail.RequestMethod || '-' }}</dd></dl>
            <dl><dt>客户端</dt><dd>{{ [logDetail.Browser, logDetail.OS].filter(Boolean).join(' · ') || '-' }}</dd></dl>
            <dl><dt>TraceId</dt><dd><button v-if="logDetail.TraceId" class="obs-link" type="button" @click="copyText(logDetail.TraceId)">{{ logDetail.TraceId }}</button><span v-else>-</span></dd></dl>
            <dl><dt>节点</dt><dd>{{ logDetail.NodeId || '-' }}</dd></dl>
          </div>
          <section class="obs-detail-section"><header><h3>标题</h3></header><p>{{ logDetail.Title || '-' }}</p></section>
          <section class="obs-detail-section"><header><h3>内容</h3><button type="button" @click="copyText(logDetail.Content)">复制</button></header><pre>{{ logDetail.Content || '-' }}</pre></section>
          <section v-if="performanceSteps.length" class="obs-detail-section"><header><h3>分步耗时</h3></header><div class="obs-performance-steps"><article v-for="(step,index) in performanceSteps" :key="`${step.name}-${index}`"><b>{{ step.name }}</b><i><em :class="`is-${step.tone}`" :style="{width:`${step.percent}%`}"></em></i><strong>{{ step.duration }}</strong><span v-if="step.detail">{{ step.detail }}</span></article></div></section>
          <section v-if="logDetail.Param" class="obs-detail-section"><header><h3>参数值</h3><button type="button" @click="copyText(logDetail.Param)">复制</button></header><pre>{{ logDetail.Param }}</pre></section>
          <section v-if="logDetail.OtherInfo" class="obs-detail-section"><header><h3>可执行 SQL / 其它信息</h3><button type="button" @click="copyText(logDetail.OtherInfo)">复制</button></header><pre>{{ logDetail.OtherInfo }}</pre></section>
          <section v-if="logDetail.Remark" class="obs-detail-section"><header><h3>备注</h3><button type="button" @click="copyText(logDetail.Remark)">复制</button></header><pre>{{ logDetail.Remark }}</pre></section>
          <section v-if="logDetail.TraceId" class="obs-detail-section"><header><h3>Trace 时间线</h3><button type="button" :disabled="traceLoading" @click="loadTrace(logDetail.TraceId)">{{ traceLoading ? '读取中…' : '刷新' }}</button></header><ol class="obs-timeline"><li v-for="item in traceRows" :key="item.Id || `${item.CreateTime}-${item.Title}`"><time>{{ formatTime(item.CreateTime || item.OccurredAt) }}</time><div><b>{{ item.Title || item.Type || '-' }}</b><p>{{ item.Content || '-' }}</p></div></li><li v-if="!traceLoading && !traceRows.length"><p>暂无关联 Trace 日志</p></li></ol></section>
        </section>
