    <Teleport to="body"><div v-if="dialog.open" class="obs-dialog-mask" @click.self="closeDialog"><section class="obs-dialog" role="alertdialog" aria-modal="true"><div class="obs-dialog__icon" :class="{ 'is-primary': dialog.mode === 'retireMenus' }">!</div><p class="obs-eyebrow">{{ dialog.mode === 'retireMenus' ? 'MENU MIGRATION' : 'SECURITY ACTION' }}</p><h2>{{ dialog.mode === 'block' ? '确认封禁 IP' : dialog.mode === 'unblock' ? '确认解封 IP' : '确认完成旧菜单合并' }}</h2><template v-if="dialog.mode === 'block'"><label><span>IP 地址</span><input v-model.trim="dialog.ip" placeholder="例如 203.0.113.20"></label><label><span>封禁时长（分钟）</span><input v-model.number="dialog.minutes" type="number" min="1" max="10080"></label><label><span>原因</span><textarea v-model.trim="dialog.reason" maxlength="300"></textarea></label><p>请先确认该地址不是可信反向代理、容器网桥或运维出口。操作会写入审计日志。</p></template><p v-else-if="dialog.mode === 'unblock'">即将解封 <b>{{ dialog.ip }}</b>，操作会写入审计日志。</p><template v-else><p>将软删除当前检测到的 {{ legacyMenus.length }} 个官方标准旧菜单。该动作可重复运行，不会删除【系统日志/监控】，也不会删除标识、名称或地址不完全匹配的租户自定义菜单。</p><div class="obs-migration-list">{{ legacyMenus.map(item => item.Name).join('、') }}</div></template><footer><button type="button" @click="closeDialog">取消</button><button type="button" :class="{ 'is-danger': dialog.mode !== 'retireMenus', 'is-primary': dialog.mode === 'retireMenus' }" :disabled="dialog.saving" @click="submitDialogAction">{{ dialog.saving ? '提交中…' : '确认操作' }}</button></footer></section></div></Teleport>
  </main>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { configureV8, dispatch, getContext, subscribeContext } from './microi'
import ObservabilityTable from './components/ObservabilityTable.vue'
import MemoryDiagnostics from './components/MemoryDiagnostics.vue'
import CdnMonitor from './components/CdnMonitor.vue'
const cdnMonitor = ref(null)
const memoryDiagnostics = ref(null)

const tabs = [{key:'logs',label:'系统日志',icon:'≡'},{key:'traffic',label:'网络流量',icon:'⇅'},{key:'cdn',label:'CDN监控/分析/安全',icon:'◎'},{key:'overview',label:'运行诊断',icon:'⌁'},{key:'requests',label:'请求与接口',icon:'⇄'},{key:'runtime',label:'系统监控',icon:'◫'},{key:'memory',label:'内存与事故',icon:'⌕'},{key:'security',label:'安全数据',icon:'◇'},{key:'appLogs',label:'应用日志',icon:'›_'}]
const rangeOptions = [{key:'live5',label:'实时（近5分钟）'},{key:'today',label:'当天'},{key:'yesterday',label:'昨天'},{key:'3d',label:'近3天'},{key:'7d',label:'近7天'},{key:'15d',label:'近15天'},{key:'30d',label:'近30天'},{key:'3m',label:'近3个月'},{key:'6m',label:'近6个月'},{key:'1y',label:'近1年'}]
const activeTab = ref('logs'), rangeKey = ref('today'), windowMinutes = ref(5), autoRefresh = ref(false), loading = ref(false), error = ref(''), notice = ref('')
const data = ref(null), snapshot = computed(() => data.value?.RequestRuntime || null), host = ref(null), docker = ref(null), platformStats = ref({}), appLogs = ref([]), trends = ref([]), legacyMenus = ref([])
const historical = ref(null), trafficHistory = ref([]), trafficHistoryError = ref(''), trafficHistoryLoading = ref(false), motionPaused = ref(document.hidden || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)
const trafficDetails = ref([]), trafficDetailCount = ref(0), trafficDetailPage = ref(1), trafficDetailPageSize = ref(15), trafficDetailKeyword = ref(''), trafficDetailLoading = ref(false)
const currentMonth = localMonth()
const logFilters = reactive({ Keyword:'', Type:'', Level:'', SearchMonth:currentMonth }), logs = ref([]), logTypes = ref([]), logStats = ref({}), logCount = ref(0), logPage = ref(1), logPageSize = ref(15), logLoading = ref(false), trace = ref(null), traceLoading = ref(false), logDetail = ref(null)
const securityKind = ref('Access'), securityKeyword = ref(''), securityRows = ref([]), securityCount = ref(0), securityPage = ref(1), securityPageSize = ref(15)
const appLogLineCount = ref(200), appLogLevel = ref('All'), appLogLoading = ref(false)
const dialog = reactive({ open:false, mode:'block', ip:'', minutes:30, reason:'', saving:false })
const theme = reactive({ dark:false, primary:'#409eff', onPrimary:'#ffffff', strong:'#337ecc' })
let timer = 0, refreshCount = 0, unsubscribe = null, lastDockerLoadedAt = 0, lastTrafficHistoryAt = 0, logRequestSequence = 0, securityRequestSequence = 0, trafficDetailRequestSequence = 0, modalDocumentScrollState = null
const reduceMotionMedia = window.matchMedia?.('(prefers-reduced-motion: reduce)')

const endpointColumns = [{key:'endpoint',label:'接口',minWidth:250,searchKeys:['ApiEngineKey','Route','Key','EndpointKind']},{key:'requests',label:'请求',width:110},{key:'share',label:'耗时占比',width:140},{key:'duration',label:'平均 / P95或最大',width:155},{key:'errors',label:'异常',width:120}]
const ipColumns = [{key:'ip',label:'来源 IP',minWidth:150,searchKeys:['Ip','Key']},{key:'requests',label:'请求 / 活动',width:110},{key:'share',label:'耗时占比',width:110},{key:'errors',label:'异常',width:80},{key:'action',label:'操作',width:65}]
const activeRequestColumns = [{key:'endpoint',label:'接口',minWidth:250,searchKeys:['ApiEngineKey','Route','TraceId','Method']},{key:'Ip',label:'IP',width:130},{key:'StartedAtUtc',label:'开始时间',width:165,format:value=>formatTime(value)},{key:'elapsed',label:'持续时间',width:95}]
const recentRequestColumns = [{key:'endpoint',label:'接口',minWidth:250,searchKeys:['ApiEngineKey','Route','TraceId','Method']},{key:'Ip',label:'IP',width:130},{key:'status',label:'状态',width:70},{key:'elapsed',label:'耗时',width:90},{key:'CompletedAtUtc',label:'完成时间',width:165,format:value=>formatTime(value)}]
const dockerColumns = [{key:'container',label:'容器',minWidth:190,searchKeys:['Name','ContainerId','State','Status']},{key:'image',label:'镜像 / 端口',minWidth:230,searchKeys:['Image','Ports']},{key:'cpu',label:'CPU',width:115},{key:'memory',label:'内存',minWidth:180},{key:'NetIO',label:'网络 IO',width:135},{key:'BlockIO',label:'块 IO',width:135},{key:'PIDs',label:'进程',width:65}]
const apiRankColumns = [{key:'engine',label:'接口引擎',minWidth:180,searchKeys:['Name','ApiEngineKey']},{key:'CallCount',label:'调用次数',width:85},{key:'time',label:'最后调用',width:165}]
const tableRankColumns = [{key:'Name',label:'表单引擎',minWidth:150,searchKeys:['Name','Description']},{key:'Description',label:'描述',minWidth:150,wrap:true},{key:'DataCount',label:'数据量',width:90}]
const loginColumns = [{key:'user',label:'用户',minWidth:150,searchKeys:['Name','Account']},{key:'IP',label:'IP',width:130},{key:'time',label:'最后登录',width:165}]
