async function query(payload){ const result=await configureV8().post('/apiengine/mci-system-observability-query',payload); if(!result||Number(result.Code)!==1) throw new Error(result?.Msg||'接口返回失败'); return result }
async function action(payload){ const result=await configureV8().post('/apiengine/mci-system-observability-action',payload); if(!result||Number(result.Code)!==1) throw new Error(result?.Msg||'操作失败'); return result }
async function loadSnapshot(forceHost=false){ if(loading.value)return; loading.value=true; try{ refreshCount++; const includeHost=forceHost||!host.value||refreshCount%3===0; const result=await query({Action:'Snapshot',WindowMinutes:windowMinutes.value,Top:20,IncludeHost:includeHost}); data.value=result.Data||{}; if(result.Data?.Host)host.value=result.Data.Host; appendTrend(); error.value='' }catch(e){error.value=e?.message||String(e)}finally{loading.value=false} }
async function loadTrafficHistory(force=false){if(trafficHistoryLoading.value||(!force&&historical.value?.Range?.Key===rangeKey.value&&Date.now()-lastTrafficHistoryAt<60000))return;trafficHistoryLoading.value=true;try{const result=await query({Action:'HistoricalDashboard',RangeKey:rangeKey.value,Top:20,ForceRefresh:Boolean(force)});historical.value=result.Data||null;trafficHistory.value=result.Data?.TrafficHistory||[];trafficHistoryError.value='';lastTrafficHistoryAt=Date.now()}catch(e){historical.value=null;trafficHistory.value=[];trafficHistoryError.value=e?.message||'暂时无法读取 MySQL 汇总历史；实时数据仍可继续查看。'}finally{trafficHistoryLoading.value=false}}
async function loadTrafficDetails(page=1){const sequence=++trafficDetailRequestSequence;trafficDetailLoading.value=true;try{const nextPage=Math.max(1,Number(page)||1);const result=await query({Action:'TrafficDetails',RangeKey:rangeKey.value,PageIndex:nextPage,PageSize:trafficDetailPageSize.value,Keyword:trafficDetailKeyword.value});if(sequence!==trafficDetailRequestSequence)return;trafficDetailPage.value=nextPage;trafficDetails.value=result.Data||[];trafficDetailCount.value=Number(result.DataCount||0);error.value=''}catch(e){if(sequence===trafficDetailRequestSequence)error.value=e?.message||String(e)}finally{if(sequence===trafficDetailRequestSequence)trafficDetailLoading.value=false}}
async function loadPlatformStats(){ try{platformStats.value=(await query({Action:'PlatformStats'})).Data||{}}catch(e){error.value=e?.message||String(e)} }
async function loadDocker(force=false){if(!force&&docker.value&&Date.now()-lastDockerLoadedAt<30000)return;dockerLoading.value=true;try{docker.value=(await query({Action:'Snapshot',WindowMinutes:windowMinutes.value,Top:5,IncludeHost:false,IncludeDocker:true})).Data?.Docker||null;lastDockerLoadedAt=Date.now();error.value=''}catch(e){error.value=e?.message||String(e)}finally{dockerLoading.value=false}}
const dockerLoading=ref(false)
async function loadLogs(page=1,refreshMeta=false){const sequence=++logRequestSequence;logLoading.value=true;try{const searchMonth=String(logFilters.SearchMonth||'').replace(/-/g,'');const request={Action:'Logs',_PageIndex:Math.max(1,Number(page)||1),_PageSize:logPageSize.value,_Keyword:logFilters.Keyword,Type:logFilters.Type,Category:logFilters.Type==='Microi.Ops'?'Operations':'',Source:logFilters.Type==='Microi.Ops'?'Microi.Ops':'',Level:logFilters.Level===''?null:Number(logFilters.Level),_SearchMonth:searchMonth};const calls=[query(request)];if(refreshMeta||!logTypes.value.length)calls.push(query({Action:'LogTypes',_Keyword:logFilters.Keyword,_SearchMonth:searchMonth}),query({Action:'LogStats',_Keyword:logFilters.Keyword,_SearchMonth:searchMonth}));const results=await Promise.all(calls);if(sequence!==logRequestSequence)return;logPage.value=request._PageIndex;logs.value=results[0].Data||[];logCount.value=Number(results[0].DataCount||0);if(results.length>1){logTypes.value=results[1].Data||[];logStats.value=results[2].Data||{}}error.value=''}catch(e){if(sequence===logRequestSequence)error.value=e?.message||String(e)}finally{if(sequence===logRequestSequence)logLoading.value=false}}
async function loadTrace(id){trace.value=null;if(!/^[0-9a-f]{32}$/i.test(String(id||'')))return;traceLoading.value=true;try{trace.value=(await query({Action:'Trace',TraceId:id,PageSize:200})).Data||null}catch(e){error.value=e?.message||String(e)}finally{traceLoading.value=false}}
async function loadSecurity(page=1){const sequence=++securityRequestSequence;try{const nextPage=Math.max(1,Number(page)||1);const result=await query({Action:'SecurityData',Kind:securityKind.value,Keyword:securityKeyword.value,PageIndex:nextPage,PageSize:securityPageSize.value});if(sequence!==securityRequestSequence)return;securityPage.value=nextPage;securityRows.value=result.Data||[];securityCount.value=Number(result.DataCount||0);error.value=''}catch(e){if(sequence===securityRequestSequence)error.value=e?.message||String(e)}}
async function loadAppLogs(){appLogLoading.value=true;try{appLogs.value=(await query({Action:'AppLogs',Lines:appLogLineCount.value})).Data||[];error.value=''}catch(e){error.value=e?.message||String(e)}finally{appLogLoading.value=false}}
async function loadLegacyMenus(){try{legacyMenus.value=(await query({Action:'LegacyMenus'})).Data||[]}catch(e){error.value=e?.message||String(e)}}
async function refreshActive(force=false){if(activeTab.value==='overview')await Promise.all([loadSnapshot(force),loadTrafficHistory(Boolean(force))]);else if(activeTab.value==='cdn')await cdnMonitor.value?.refresh();else if(activeTab.value==='memory')await memoryDiagnostics.value?.refresh();else if(activeTab.value==='requests')await loadSnapshot(force);else if(activeTab.value==='traffic')await Promise.all([loadSnapshot(false),loadTrafficHistory(Boolean(force)),loadTrafficDetails(trafficDetailPage.value)]);else if(activeTab.value==='runtime')await Promise.all([loadSnapshot(true),loadPlatformStats(),loadDocker(Boolean(force))]);else if(activeTab.value==='logs')await loadLogs(logPage.value,false);else if(activeTab.value==='security')await Promise.all([loadSnapshot(false),loadSecurity(securityPage.value)]);else await loadAppLogs()}
function selectTab(key){if(activeTab.value===key)return;activeTab.value=key;void refreshActive(key==='runtime'||key==='traffic')}
function changeAnalysisRange(){lastTrafficHistoryAt=0;historical.value=null;trafficHistory.value=[];trafficDetailPage.value=1;trafficDetails.value=[];trafficDetailCount.value=0;void refreshActive(true)}
function selectSecurityKind(key){securityKind.value=key;loadSecurity(1)}
function changeSecurityPageSize(size){securityPageSize.value=Number(size)||15;void loadSecurity(1)}
function changeLogPageSize(size){logPageSize.value=Number(size)||15;void loadLogs(1,false)}
function changeTrafficDetailPageSize(size){trafficDetailPageSize.value=Number(size)||15;void loadTrafficDetails(1)}
function searchTrafficDetails(keyword){trafficDetailKeyword.value=String(keyword||'').substring(0,100);void loadTrafficDetails(1)}
function openTraceFromTraffic(row){activeTab.value='logs';if(row?.TraceId){logFilters.Keyword=String(row.TraceId);void loadLogs(1,true)}notice.value='已按 TraceId 切换到系统日志；打开匹配日志可查看完整调用时间线。'}
function resetLogFilters(){Object.assign(logFilters,{Keyword:'',Type:'',Level:'',SearchMonth:currentMonth});void loadLogs(1,true)}
function isLogQuickActive(item){if(item.key==='types')return false;return String(logFilters.Type||'')===String(item.type||'')&&String(logFilters.Level)===(item.level===''?'':String(item.level))}
function applyLogQuickFilter(item){logFilters.Type=item.type||'';logFilters.Level=item.level===''?'':Number(item.level);void loadLogs(1,true)}
function openLogDetail(row){logDetail.value=row;trace.value=null;if(row?.TraceId)void loadTrace(row.TraceId)}
function closeLogDetail(){logDetail.value=null;trace.value=null;traceLoading.value=false}
function openBlock(ip){Object.assign(dialog,{open:true,mode:'block',ip:ip||'',minutes:30,reason:'',saving:false})}
function confirmUnblock(ip){Object.assign(dialog,{open:true,mode:'unblock',ip,minutes:30,reason:'',saving:false})}
function openLegacyMigration(){Object.assign(dialog,{open:true,mode:'retireMenus',ip:'',minutes:30,reason:'',saving:false})}
function closeDialog(){if(!dialog.saving)dialog.open=false}
async function submitDialogAction(){dialog.saving=true;try{if(dialog.mode==='retireMenus'){const result=await action({Action:'RetireLegacyMenus'});dialog.open=false;notice.value=result.Msg||'旧菜单已完成合并，请刷新平台菜单。';await loadLegacyMenus();await loadPlatformStats()}else{await action({Action:dialog.mode==='block'?'BlockIp':'UnblockIp',Ip:dialog.ip,BlockMinutes:dialog.minutes,Reason:dialog.reason});dialog.open=false;await loadSnapshot(false);await loadSecurity(1)}error.value=''}catch(e){error.value=e?.message||String(e)}finally{dialog.saving=false}}
function appendTrend(){const m=host.value?.CpuMemory||{},n=host.value?.Network||{},t=traffic.value||{};trends.value=[...trends.value.slice(-59),{at:Date.now(),cpu:Number(m.CpuUsagePercent??process.value.ProcessCpuPercentNormalized??0),mem:Number(m.MemoryUsagePercent??0),rx:Number(n.ReceiveBytesPerSecond??n.RxBytesPerSecond??Number(n.RxSpeedKBps||0)*1024),tx:Number(n.SendBytesPerSecond??n.TxBytesPerSecond??Number(n.TxSpeedKBps||0)*1024),trafficRx:Number(t.ReceiveBytesPerSecond||0),trafficTx:Number(t.SendBytesPerSecond||0)}]}
function trendPoints(key,fixedMax=0){const rows=trends.value;if(!rows.length)return '';const max=fixedMax||Math.max(1,...rows.map(x=>Number(x[key]||0)));return rows.map((row,index)=>`${rows.length===1?100:index*100/(rows.length-1)},${60-Math.min(60,Number(row[key]||0)*60/max)}`).join(' ')}
function number(value,digits=0){const n=Number(value);return Number.isFinite(n)?n.toFixed(digits):'-'}
function localMonth(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`}
function duration(value){const n=Number(value||0);return n>=1000?`${number(n/1000,2)}s`:`${number(n,0)}ms`}
function rate(value){const n=Number(value||0);if(n>=1024*1024)return `${number(n/1024/1024,2)} MB/s`;if(n>=1024)return `${number(n/1024,1)} KB/s`;return `${number(n,0)} B/s`}
function bytes(value){const n=Math.max(0,Number(value||0));if(n>=1024**4)return `${number(n/1024**4,2)} TB`;if(n>=1024**3)return `${number(n/1024**3,2)} GB`;if(n>=1024**2)return `${number(n/1024**2,2)} MB`;if(n>=1024)return `${number(n/1024,1)} KB`;return `${number(n,0)} B`}
function trafficHistoryPoints(key){const groups=new Map();for(const row of trafficHistory.value||[]){const time=new Date(row.BucketStartUtc).getTime();if(!Number.isFinite(time))continue;const model=groups.get(time)||{at:time,ReceivedBytes:0,SentBytes:0};model[key]=Number(model[key]||0)+Number(row[key]||0);groups.set(time,model)}const rows=[...groups.values()].sort((a,b)=>a.at-b.at);if(!rows.length)return'';const max=Math.max(1,...rows.map(row=>Number(row[key]||0)));return rows.map((row,index)=>`${rows.length===1?100:index*100/(rows.length-1)},${60-Math.min(60,Number(row[key]||0)*60/max)}`).join(' ')}
function formatTime(value){if(!value)return '-';const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toLocaleString()}
function metricTone(value,warn,danger){const n=Number(value||0);return n>=danger?'is-danger-text':n>=warn?'is-warning-text':''}
function levelMeta(value){const level=Number(value);return ({0:{label:'调试',tone:'muted'},1:{label:'信息',tone:'info'},2:{label:'警告',tone:'warning'},3:{label:'错误',tone:'danger'},4:{label:'严重',tone:'danger'}})[level]||{label:value==null?'-':`L${value}`,tone:'muted'}}
function logDuration(row){const value=row?.Timer??row?.DurationMs;const result=Number(value);return Number.isFinite(result)?result:0}
function riskLabel(value){return({Critical:'严重',Warning:'警告',Info:'提示',Normal:'正常'})[String(value||'Normal')]||String(value||'正常')}
function trafficRowClass(row){const level=String(row?.RiskLevel||'').toLowerCase();if(level==='critical'||Number(row?.SuspiciousCount||0)>0)return'is-danger-row';if(level==='warning'||Number(row?.ErrorCount||0)>0)return'is-warning-row';return''}
function trafficRiskTooltip(row){if(row?.RiskReason||row?.Solution)return`原因：${row.RiskReason||'待结合上下文确认'}\n解决方案：${row.Solution||'核对接口、身份、IP、分页、压缩、限流与对象存储策略。'}`;if(Number(row?.SuspiciousCount||0)>0)return'原因：存在匿名上传、大流量或失败大响应。\n解决方案：核对来源 IP、接口权限和调用频率；必要时限流/封禁，大文件改对象存储直传或 CDN。';if(Number(row?.ErrorCount||0)>0)return'原因：该维度出现 4xx/5xx 或执行异常。\n解决方案：按 TraceId 查看系统日志，检查鉴权、参数、依赖服务和调用方重试。';return'当前聚合未发现明显异常；如持续占比过高，请检查分页、压缩、缓存、Range/CDN 与轮询频率。'}
function endpointKind(value){const text=String(value||'');if(text.startsWith('/apiengine/'))return'ApiEngine 接口引擎';if(text.includes('/FormEngine/'))return'FormEngine 表单引擎';return'Controller 固定 API'}
function logRowClass(row){const level=Number(row?.Level||0),type=String(row?.Type||'').toLowerCase(),elapsed=logDuration(row);if(level>=3||type.includes('exception')||type.includes('异常'))return'is-danger-row';if(level===2||elapsed>=1000||type.includes('慢'))return'is-warning-row';return''}
